"""Complete 44 original systemic vasculitis questions."""
from create_rheum_anca import rows,q,V,IM,A,K,ref
from qbank_authoring import finalize
PN=ref('ACR/VF 2021 polyarteritis nodosa guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC12323812/')
IG=ref('KDIGO 2025 IgA nephropathy and vasculitis guideline','https://kdigo.org/guidelines/igA-nephropathy/')
BE=ref('EULAR Behcet syndrome management: 2025 update, published 2026','https://doi.org/10.1016/j.ard.2026.02.009')

q('A patient has painful nodules, livedo reticularis, mononeuritis multiplex, hypertension and abdominal ischemic pain. Angiography shows renal and mesenteric microaneurysms. Which diagnosis best fits?', 'Polyarteritis nodosa',[
 ('Microscopic polyangiitis','MPA is a small-vessel capillaritis/GN phenotype rather than the classic medium-artery microaneurysm pattern.'),('IgA vasculitis','This is an immune-complex small-vessel disease and does not best explain these arterial microaneurysms.'),('Primary antiphospholipid syndrome','Thrombosis can cause ischemia and livedo, but the arterial inflammatory microaneurysm phenotype favors PAN.')],
 'Recognize necrotizing medium-artery disease','**PAN can produce visceral ischemia, skin lesions and ischemic neuropathy.**',['Renal artery involvement causes hypertension or ischemia rather than typical glomerulonephritis.','Histology or vascular imaging establishes evidence according to the affected site.'], '**Assess threatened viscera and nerve function promptly.**',['Review hepatitis B status and other secondary causes.','Choose treatment according to severity and etiology.'],[['Medium arteries','Ischemia/microaneurysms'],['Kidney','Vascular hypertension rather than typical GN'],['Nerves','Mononeuritis multiplex']],[PN],style='clinical_scenario')

q('Which finding is least typical of classic PAN and should prompt reconsideration of the diagnosis?', 'Pulmonary capillaritis with pauci-immune crescentic glomerulonephritis',[
 ('Mesenteric ischemia','This is a recognized medium-artery manifestation.'),('Mononeuritis multiplex','This is characteristic of ischemic vasculitic neuropathy.'),('Renovascular hypertension','This can result from renal arterial involvement.')],
 'Use vessel size and target anatomy to refine the diagnosis','**Classic PAN generally spares pulmonary capillaries and does not cause the typical AAV glomerular lesion.**',['A pulmonary-renal capillaritis syndrome suggests AAV, anti-GBM or another small-vessel process.','ANCA positivity does not define PAN.'], '**Reassess pathology and the systemic pattern.**',['Renal impairment in PAN can be vascular, so distinguish it from active GN.','The distinction changes testing and treatment pathways.'],[['PAN','Medium-artery disease'],['GN/capillaritis','Small-vessel process'],['Renal hypertension','Compatible with PAN']],[PN,A])

q('A patient has severe non-hepatitis-B-associated PAN with mesenteric ischemia. Which induction strategy is generally appropriate?', 'Glucocorticoids plus cyclophosphamide',[
 ('Colchicine alone','This is insufficient for severe visceral vasculitis.'),('Hydroxychloroquine alone','This is not adequate organ-threatening PAN induction.'),('Antiviral therapy alone without a viral association','A nonviral severe PAN syndrome needs an appropriate immunosuppressive strategy.')],
 'Severity and etiology determine the regimen','**Severe systemic PAN usually requires glucocorticoids with cyclophosphamide induction.**',['Nonsevere disease can use different steroid-sparing approaches.','HBV-associated disease requires a distinct antiviral-centered specialist strategy rather than uncritical prolonged immunosuppression.'], '**Manage ischemic complications as well as inflammation.**',['Assess for bowel infarction or other surgical emergencies.','Plan maintenance and cumulative-toxicity prevention after response.'],[['Severe non-HBV PAN','GC + cyclophosphamide'],['Nonsevere disease','Different risk-adjusted strategy'],['HBV-associated PAN','Etiology-specific treatment']],[PN],style='clinical_scenario')

q('Palpable lower-limb purpura, abdominal colic, arthralgia and hematuria with normal platelet count suggest which diagnosis?', 'IgA vasculitis',[
 ('Immune thrombocytopenia','The platelet count is normal and the renal/GI pattern suggests vascular inflammation.'),('Classic PAN','This has a different medium-artery phenotype.'),('GPA','Granulomatous airway disease and pauci-immune rather than IgA-deposit disease would be more characteristic.')],
 'Recognize the skin–joint–gut–kidney pattern','**IgA vasculitis is a small-vessel immune-complex disease.**',['Purpura is typically nonthrombocytopenic.','Biopsy with direct immunofluorescence can show IgA-dominant deposits when needed.'], '**Assess renal and gastrointestinal severity.**',['Check blood pressure, urine protein, sediment and kidney function.','Severe abdominal pain requires evaluation for bleeding, intussusception or other complications.'],[['Skin','Palpable purpura'],['Kidney','Hematuria/proteinuria'],['Gut','Pain and potential bleeding']],[IG],style='clinical_scenario')

q('A child has IgA vasculitis without kidney involvement. Should systemic glucocorticoids be prescribed solely to prevent future nephritis?', 'No; they have not shown a preventive renal benefit for this purpose',[
 ('Yes, in every case regardless of symptoms','Evidence does not support universal prophylactic glucocorticoids for nephritis prevention.'),('Yes, but only when the serum IgA is normal','Serum IgA does not create this indication.'),('Yes, until all skin lesions have been absent for a year','This prolonged prevention strategy is unsupported and adds toxicity.')],
 'Do not confuse treatment of severe symptoms with renal prevention','**Glucocorticoids may be used for selected serious manifestations but not solely as proven prophylaxis against nephritis.**',['Kidney surveillance is still necessary after the initial presentation.','Treat established renal disease according to severity and current guidance.'], '**Explain the follow-up plan rather than promise prevention from steroids.**',['Monitor urine and blood pressure over the appropriate interval.','Escalate assessment if proteinuria, hypertension or renal impairment develops.'],[['No nephritis','Surveillance remains important'],['Steroid prophylaxis','No established renal prevention benefit'],['Established organ disease','Severity-directed care']],[IG],style='clinical_scenario')

q('Which feature most directly determines long-term renal concern in IgA vasculitis?', 'Persistent clinically important proteinuria and impaired kidney function',[
 ('The number of transient skin lesions alone','Skin burden does not reliably define long-term renal prognosis.'),('The intensity of a single ankle arthralgia episode','Joint pain alone does not quantify kidney risk.'),('A positive ANA without renal findings','This does not define IgAV renal progression risk.')],
 'Follow objective renal outcomes','**Persistent protein excretion, kidney function and blood pressure guide renal risk assessment.**',['Adults can have more consequential renal disease than a mild skin presentation suggests.','A severe or atypical renal course may require biopsy.'], '**Continue urine and BP follow-up even as purpura resolves.**',['Provide renoprotective care and specialist treatment when indicated.','Do not use symptom resolution as proof that the kidney is unaffected.'],[['Proteinuria','Key risk and response marker'],['Kidney function','Measures organ impact'],['Skin improvement','Does not end renal follow-up']],[IG])

q('A patient has hepatitis C, palpable purpura, arthralgia, neuropathy, low C4 and immune-complex GN. Which diagnosis is most likely?', 'Mixed cryoglobulinemic vasculitis',[
 ('GPA','This more typically produces pauci-immune disease rather than this low-complement immune-complex context.'),('Primary PAN','PAN does not classically cause immune-complex glomerulonephritis.'),('Primary Raynaud phenomenon','This cannot explain the systemic vasculitic renal pattern.')],
 'Recognize a viral-driven immune-complex syndrome','**Mixed cryoglobulinemia can cause skin, nerve and renal injury, with low C4 as a useful clue.**',['HCV is an important cause, but autoimmune and lymphoproliferative disorders are also possible.','Specimen handling matters because cryoglobulins can be missed if the sample is not handled correctly.'], '**Treat the underlying driver and organ-threatening inflammation.**',['Direct-acting antiviral therapy addresses HCV.','Severe vasculitic injury may require additional immune treatment and selected plasma exchange.'],[['Low C4','Immune-complex clue'],['HCV','Treatable driver'],['Severe renal/nerve disease','May need combined treatment']],[ref('KDIGO hepatitis C in CKD guideline: 2022','https://kdigo.org/guidelines/hepatitis-c-in-ckd/')],style='clinical_scenario')

q('Why must a blood specimen for cryoglobulin assessment be kept warm until serum separation according to laboratory protocol?', 'Premature precipitation can remove cryoglobulins from the analyzed serum and cause a false-negative result',[
 ('Cooling permanently destroys all complement proteins within seconds','This is not the principal reason for the collection requirement.'),('Warming converts monoclonal cryoglobulin to a polyclonal antibody','Temperature handling does not change clonality.'),('The sample is intended only to measure serum urate solubility','This is a different test.')],
 'A preanalytical error can hide the disease mechanism','**Cryoglobulins precipitate when cooled and must be assessed using the correct collection pathway.**',['Laboratory protocols commonly require warm handling through serum separation.','Typing, concentration and the clinical setting are interpreted after detection.'], '**Discuss testing with the laboratory when suspicion is high.**',['Repeat an improperly handled negative sample if necessary.','Do not diagnose the full vasculitic syndrome from a low-level incidental result alone.'],[['Warm handling','Prevents premature sample loss'],['Cold incubation after processing','Used for detection'],['Clinical context','Defines significance']],[ref('Laboratory recommendations for cryoglobulin detection and characterization','https://doi.org/10.1093/clinchem/hvab195')])

q('A young adult has recurrent oral aphthae, genital ulcers with scars, inflammatory eye disease and erythema-nodosum-like lesions. Which diagnosis best fits?', 'Behcet syndrome',[
 ('Recurrent simple aphthosis alone','This does not explain the genital, ocular and systemic inflammatory pattern.'),('Reactive arthritis','It can overlap mucocutaneous/ocular findings, but the recurrent genital scarring and multisystem pattern favor Behcet.'),('Primary Sjogren disease','Sicca rather than this ulcerative-vascular phenotype would be characteristic.')],
 'Recognize a variable-vessel systemic inflammatory phenotype','**Behcet can involve mucosa, skin, eyes, vessels, nervous system and gut.**',['There is no single diagnostic blood test.','Infectious and other inflammatory causes of ulcers must be considered.'], '**Determine which organ is threatened now.**',['Eye or vascular involvement changes treatment urgency.','Pathergy and HLA-B51 can support context but do not independently establish the diagnosis.'],[['Mucosal ulcers','Recurrent pattern'],['Eye disease','Potential sight threat'],['Vascular disease','Arterial or venous involvement']],[BE],style='clinical_scenario')

q('A Behcet patient has acute sight-threatening posterior uveitis. Which treatment principle is appropriate under the updated EULAR framework?', 'Urgent systemic treatment with a monoclonal anti-TNF strategy, preferably infliximab in an appropriate combination, rather than topical treatment alone',[
 ('Topical lubricants alone','These do not control posterior sight-threatening inflammation.'),('Colchicine alone as definitive ocular induction','It is not adequate treatment for this severity and organ domain.'),('Delay systemic therapy until a pathergy test becomes positive','A diagnostic supportive test must not delay vision-preserving treatment.')],
 'Treat the eye according to location and severity','**Posterior-segment sight-threatening Behcet inflammation requires urgent systemic therapy.**',['The 2025 EULAR update emphasizes monoclonal anti-TNF treatment in this setting.','Ophthalmological monitoring and adjunctive immune treatment are individualized.'], '**Coordinate specialist care immediately.**',['Exclude relevant infectious ocular disease.','Do not extrapolate a mucocutaneous regimen to severe retinal vasculitis.'],[['Mucocutaneous disease','Different treatment intensity'],['Posterior eye disease','Urgent systemic control'],['Infliximab','Preferred anti-TNF option in the updated severe-eye context']],[BE],style='clinical_scenario')

q('A Behcet patient develops DVT and hemoptysis. What must be evaluated before adding anticoagulation?', 'Pulmonary artery aneurysm and the associated bleeding risk',[
 ('Only serum urate','This does not define pulmonary vascular bleeding risk.'),('Only rheumatoid factor','RF does not address the urgent vascular question.'),('Only a routine eye refraction','This does not evaluate the cause of hemoptysis.')],
 'Behcet thrombosis is linked to vessel-wall inflammation','**Aneurysmal pulmonary arterial disease can make anticoagulation hazardous.**',['Immune control is central to vascular Behcet treatment.','Anticoagulation may be added in selected circumstances when bleeding risk is low and aneurysm has been excluded.'], '**Investigate hemoptysis promptly and coordinate vascular/pulmonary care.**',['Do not treat every Behcet thrombosis exactly like uncomplicated conventional VTE.','Aneurysm treatment can require potent immunosuppression and selected embolization or other intervention.'],[['DVT','Inflammatory vascular disease possible'],['Hemoptysis','Assess pulmonary arterial lesions'],['Anticoagulation','Risk-based after aneurysm assessment']],[BE,ref('BAD/BSR Behcet living guideline: 2025','https://doi.org/10.1093/bjd/ljaf383')],style='clinical_scenario')

q('A young heavy smoker has distal ischemic ulcers, digital claudication and migratory superficial thrombophlebitis without a typical atherosclerotic risk profile. Which diagnosis is most likely?', 'Thromboangiitis obliterans',[
 ('Takayasu arteritis','This predominantly affects the aorta and major branches rather than the characteristic distal tobacco-associated pattern.'),('Giant cell arteritis','The age and distribution are not typical.'),('Primary Raynaud phenomenon','Tissue-threatening ischemia and thrombophlebitis require another explanation.')],
 'Recognize a tobacco-associated distal occlusive disease','**Buerger disease affects distal small- and medium-sized vessels and has a strong tobacco association.**',['Exclude embolic disease, autoimmune vasculitis, atherosclerosis and thrombophilia as appropriate.','Complete cessation of tobacco exposure is central to preventing progression.'], '**Treat threatened tissue and support cessation intensively.**',['Assess infection, wounds and vascular options.','Routine immunosuppression is not equivalent to treating an autoimmune necrotizing vasculitis.'],[['Distribution','Distal vessels'],['Association','Tobacco'],['Core intervention','Complete exposure cessation']],[ref('Thromboangiitis obliterans clinical review','https://pmc.ncbi.nlm.nih.gov/articles/PMC2880529/')],style='clinical_scenario')

q('A patient has new palpable purpura after starting an antibiotic, with normal urine, creatinine and no systemic symptoms. What is the appropriate initial principle?', 'Assess for skin-limited small-vessel vasculitis, review the trigger and screen for systemic involvement',[
 ('Assume systemic AAV and give cyclophosphamide immediately','Skin-limited disease and a drug trigger may have a much different risk-benefit profile.'),('Ignore the eruption because platelets are normal','Normal platelets do not exclude vascular inflammation.'),('Diagnose IgA vasculitis solely from any purple lesion','Specific attribution requires the pattern and selected biopsy/immunofluorescence evidence.')],
 'Determine extent before choosing treatment intensity','**Leukocytoclastic skin vasculitis can be drug-associated or skin-limited.**',['Ask about renal, gastrointestinal, joint, pulmonary and neurological symptoms.','Biopsy a suitable fresh lesion, with separate material for direct immunofluorescence when indicated.'], '**Withdraw a plausible culprit when appropriate and monitor the course.**',['Urinalysis and kidney assessment help identify occult systemic disease.','Escalate treatment for significant systemic or severe persistent cutaneous disease.'],[['Skin histology','Defines vascular injury'],['Urine/organ screen','Defines extent'],['Treatment intensity','Depends on extent and severity']],[ref('Cutaneous vasculitis diagnostic algorithm','https://pmc.ncbi.nlm.nih.gov/articles/PMC9532537/')],style='clinical_scenario')

q('A patient has recurrent urticarial lesions lasting longer than 24 hours, burning pain, residual bruising and low complement. Which diagnosis deserves consideration?', 'Hypocomplementemic urticarial vasculitis',[
 ('Ordinary transient urticaria','Individual ordinary wheals usually resolve within 24 hours without residual purpura.'),('Simple pressure-related flushing','This does not explain the duration, bruising and complement pattern.'),('Isolated xerosis','Dry skin does not produce the stated lesion pattern.')],
 'Duration and residual change distinguish a vascular eruption','**Urticarial vasculitis can cause persistent painful or burning wheals with residual pigmentation/purpura.**',['Low complement raises concern for a systemic phenotype.','SLE and other associated disorders should be assessed.'], '**Obtain appropriate skin pathology and evaluate organ involvement.**',['Ask about joint, renal, pulmonary and gastrointestinal symptoms.','Treatment differs from uncomplicated histamine-mediated urticaria.'],[['Ordinary urticaria','Transient wheals'],['Urticarial vasculitis','Persistent lesions/residual change'],['Low complement','Systemic assessment warranted']],[ref('Urticarial vasculitis clinical-pathological review','https://pmc.ncbi.nlm.nih.gov/articles/PMC8243153/')],style='clinical_scenario')

q('A patient has fever, a new cardiac murmur, low complement, GN and positive ANCA. What important mimic must be excluded before labeling primary AAV?', 'Infective endocarditis-associated immune phenomena',[
 ('Primary osteoarthritis','This does not unify the infectious/renal phenotype.'),('Uncomplicated Raynaud phenomenon','This does not explain fever, murmur and GN.'),('Isolated migraine','This does not explain the systemic findings.')],
 'An ANCA result does not exclude infection','**Endocarditis can cause glomerulonephritis, complement consumption and autoimmune serological findings.**',['Blood cultures and echocardiography are important in a compatible presentation.','Antibiotics before cultures can reduce microbiological yield.'], '**Evaluate infection promptly before uncritical immune escalation.**',['Immune treatment in uncontrolled infection can cause substantial harm.','A pulmonary-renal or systemic vasculitic phenotype still needs urgent mechanism-based assessment.'],[['Fever/murmur','Consider endocarditis'],['Low complement/GN','Immune-complex mechanism possible'],['ANCA positive','Not unique to primary AAV']],[A,ref('ESC endocarditis guideline: 2023','https://doi.org/10.1093/eurheartj/ehad193')],style='clinical_scenario')

q('A child has PAN-like livedo and vasculitis, recurrent early strokes and cytopenias. Which inherited disorder should be investigated?', 'Deficiency of adenosine deaminase 2',[
 ('Familial Mediterranean fever as established from livedo alone','FMF more typically causes recurrent fever/serositis and does not best explain this stroke/vasculitic marrow phenotype.'),('Hereditary angioedema','This does not produce the stated vasculitis and recurrent stroke syndrome.'),('Wilson disease','Its hepatic/neurological phenotype does not explain the characteristic PAN-like inflammatory vasculopathy.')],
 'Early-onset vasculopathy can be monogenic','**DADA2 can cause livedoid/PAN-like disease, strokes, cytopenias and immune abnormalities.**',['Diagnosis uses appropriate ADA2 activity and/or genetic assessment.','Phenotypes can emphasize vasculitis, marrow failure or immune dysfunction.'], '**Refer for specialist genetic and immune evaluation.**',['TNF inhibition has important evidence for reducing vasculitic/stroke risk.','Severe marrow/immune phenotypes may need different strategies, including selected HSCT.'],[['DADA2','Monogenic vasculopathy'],['TNF inhibition','Important vasculitic treatment'],['Marrow failure','May change the treatment pathway']],[ref('DADA2 original anti-TNF treatment report','https://www.nejm.org/doi/full/10.1056/NEJMc1801927'),ref('GeneReviews: ADA2 deficiency','https://www.ncbi.nlm.nih.gov/books/NBK544951/')],style='clinical_scenario')

if __name__=='__main__':finalize('Rheumatology',7,'Systemic Vasculitis','rheum-vasculitis',rows,44)
